# Fix the BFS and check for interior holes
from collections import deque

lines = grid_data.strip().split('\n')
grid = [list(map(int, l.split())) for l in lines]
height, width = len(grid), len(grid[0])

visited_border = set()
queue = deque([])

for r in range(height):
    for c in [0, width-1]:
        if grid[r][c] == 9:
            queue.append((r,c))
            visited_border.add((r,c))
for c in range(width):
    for r in [0, height-1]:
        if grid[r][c] == 9 and (r,c) not in visited_border:
            queue.append((r,c))
            visited_border.add((r,c))

while queue:
    r, c = queue.popleft()
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < height and 0 <= nc < width:
            if grid[nr][nc] == 9 and (nr, nc) not in visited_border:
                visited_border.add((nr, nc))
                queue.append((nr, nc))

internal_9s = [(r,c) for r in range(height) for c in range(width) 
               if grid[r][c] == 9 and (r,c) not in visited_border]
print(f"Found {len(internal_9s)} interior 9s (holes):")
print(internal_9s)

# Also show non-border reachable cells (the whole grid minus border-connected 9s)
all_non_border_9 = set([(r,c) for r in range(height) for c in range(width) if grid[r][c] == 9])
not_reachable_from_border = all_non_border_9 - visited_border
print(f"\nTotal 9s: {len(all_non_border_9)}, Reachable from border: {len(visited_border)}")

